def _line(write, text=""):
    if write: write(text + "\n")
    else: print(text)


async def main(argv=None, cwd="/", read_char=None, write=None):
    s = _image.load_bytes(JPEG_BYTES)
    _line(write, "sdl_jpeg: decoded " + str(s.w) + "x" + str(s.h) + " surface")
    o = (4*s.w + 4) * 4
    _line(write, "sdl_jpeg: px(4,4)=" + str(list(s.pixels[o:o+4])))
    _line(write, "sdl_jpeg: ok")
